def zendesk_list_tickets(status=None, priority=None, assignee_email=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0173000" if __import__("os").path.isdir("./environment_mix/0173000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")

    def _ensure_world_dict(x):
        # world.json is declared as "0 rows" in the digest; normalize to a dict container we can read from.
        if isinstance(x, dict):
            return x
        if isinstance(x, list):
            # if it's a list of rows, use the first dict row if available; else start fresh
            for r in x:
                if isinstance(r, dict):
                    return r
            return {}
        return {}

    world = _ensure_world_dict(world)

    def _append_request_log(ok, error_code=None):
        nonlocal world
        try:
            usage = world.get("usage")
            if not isinstance(usage, dict):
                usage = {}
                world["usage"] = usage
            reqs = usage.get("requests")
            if not isinstance(reqs, list):
                reqs = []
                usage["requests"] = reqs

            usage["total_requests"] = int(usage.get("total_requests") or 0) + 1
            if not ok:
                usage["total_errors"] = int(usage.get("total_errors") or 0) + 1
            else:
                usage["total_errors"] = int(usage.get("total_errors") or 0)

            reqs.append({
                "id": f"req_{int(time.time()*1000)}_{len(reqs)+1}",
                "endpoint": "zendesk_list_tickets",
                "status": "ok" if ok else "error",
                "error_code": error_code,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("world.json", world)
        except Exception:
            # Never raise from logging; endpoint should still return its main result.
            return

    # Validate inputs
    allowed_status = {"open", "pending", "solved", "closed"}
    allowed_priority = {"low", "normal", "high", "urgent"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _append_request_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported status value.", allowed=sorted(allowed_status))
    if priority is not None and (not isinstance(priority, str) or priority not in allowed_priority):
        _append_request_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported priority value.", allowed=sorted(allowed_priority))
    if assignee_email is not None and not isinstance(assignee_email, str):
        _append_request_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "assignee_email must be a string.")

    # Read tickets from the real collection
    tickets = world.get("tickets")
    if not isinstance(tickets, list):
        tickets = []

    # Filter
    out = []
    for t in tickets:
        if not isinstance(t, dict):
            continue
        if status is not None and t.get("status") != status:
            continue
        if priority is not None and t.get("priority") != priority:
            continue
        if assignee_email is not None:
            # If assignee_email filter is provided, only include tickets whose assignee matches exactly.
            if t.get("assignee_email") != assignee_email:
                continue
        out.append(t)

    # Sort by created_at ascending if present, otherwise stable
    def _created_key(row):
        v = row.get("created_at")
        return v if isinstance(v, str) else ""
    out.sort(key=_created_key)

    _append_request_log(True)
    return {
        "tickets": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None
    }

def zendesk_get_ticket(id, **_extra):
