            if not isinstance(usage, dict):
                usage = {}
                world["usage"] = usage
            reqs = usage.get("requests")
            if not isinstance(reqs, list):
                reqs = []
                usage["requests"] = reqs
            usage.setdefault("total_requests", 0)
            usage.setdefault("total_errors", 0)

            usage["total_requests"] += 1
            if status != "ok":
                usage["total_errors"] += 1

            reqs.append({
                "id": f"req_{int(time.time()*1000)}_{len(reqs)+1}",
                "endpoint": "zendesk_get_ticket",
                "status": status,
                "error_code": error_code,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("world.json", world)
        except Exception:
            return

    # Validate id
    if id is None or not isinstance(id, str) or not id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing required parameter: id.")
    if not re.fullmatch(r"(TICKET|T|ZD)[-_]?\d+", id.strip()) and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{2,63}", id.strip()):
        # accept common ticket-ish ids but refuse clearly malformed ones
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid ticket id format.")

    tickets = world.get("tickets", []) if isinstance(world, dict) else []
    comments = world.get("comments", []) if isinstance(world, dict) else []
    if not isinstance(tickets, list): tickets = []
    if not isinstance(comments, list): comments = []

    ticket = None
    for t in tickets:
        if isinstance(t, dict) and t.get("id") == id:
            ticket = t
            break

    if ticket is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Ticket not found.", id=id)

    ticket_comments = [c for c in comments if isinstance(c, dict) and c.get("ticket_id") == id]

    _log("ok")
    return {"ticket": ticket, "comments": ticket_comments}

