        except Exception:
            return

    # Validate
    if id is None or not isinstance(id, str) or not id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing required parameter: id.")
    if not re.fullmatch(r"(TICKET|T|ZD)[-_]?\d+", id.strip()) and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{2,63}", id.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid ticket id format.")

    allowed_status = {"open", "pending", "solved", "closed"}
    allowed_priority = {"low", "normal", "high", "urgent"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported status value.", allowed=list(sorted(allowed_status)))
    if priority is not None and (not isinstance(priority, str) or priority not in allowed_priority):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported priority value.", allowed=list(sorted(allowed_priority)))
    if assignee_email is not None and not isinstance(assignee_email, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "assignee_email must be a string.")

    if status is None and priority is None and assignee_email is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No updatable fields provided.")

    tickets = world.get("tickets", []) if isinstance(world, dict) else []
    if not isinstance(tickets, list):
        tickets = []
        if isinstance(world, dict):
            world["tickets"] = tickets

    idx = None
    for i, t in enumerate(tickets):
        if isinstance(t, dict) and t.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Ticket not found.", id=id)

    current = tickets[idx]
    if not isinstance(current, dict):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Ticket record is corrupted.", id=id)

    updated = dict(current)
    changed = False
    if status is not None and updated.get("status") != status:
        updated["status"] = status
        changed = True
    if priority is not None and updated.get("priority") != priority:
        updated["priority"] = priority
        changed = True
    if assignee_email is not None and updated.get("assignee_email") != assignee_email:
        updated["assignee_email"] = assignee_email
        changed = True

    if not changed:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Update would not change anything.")

    # audit timestamps if present
    now = datetime.datetime.utcnow().isoformat() + "Z"
    if "updated_at" in updated or "created_at" in updated:
        updated["updated_at"] = now

    tickets[idx] = updated
