def gmail_send_email(to, subject, body, cc=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0173000" if __import__("os").path.isdir("./environment_mix/0173000") else "/app/database")
