    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")

    def _log(status, error_code=None):
        nonlocal world
        try:
            if not isinstance(world, dict):
                world = {}
            usage = world.get("usage")
            if not isinstance(usage, dict):
                usage = {}
                world["usage"] = usage
            reqs = usage.get("requests")
            if not isinstance(reqs, list):
                reqs = []
                usage["requests"] = reqs
            usage.setdefault("total_requests", 0)
            usage.setdefault("total_errors", 0)

            usage["total_requests"] += 1
            if status != "ok":
                usage["total_errors"] += 1

            reqs.append({
                "id": f"req_{int(time.time()*1000)}_{len(reqs)+1}",
                "endpoint": "gmail_send_email",
                "status": status,
                "error_code": error_code,
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("world.json", world)
        except Exception:
            return

    def _is_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if len(s) < 3 or len(s) > 254:
            return False
        # simple but practical email check
        return re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", s) is not None

    # Validate required params
    if not isinstance(to, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "to must be an array of email addresses.")
    if len(to) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Recipient list 'to' must not be empty.")
    if any(not _is_email(x) for x in to):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "One or more 'to' recipients are invalid.")
    if not isinstance(subject, str) or subject == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subject is required and must be a string.")
    if not isinstance(body, str) or body == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body is required and must be a string.")

    if cc is None:
        cc_list = []
    else:
        if not isinstance(cc, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cc must be an array of email addresses.")
        if any(not _is_email(x) for x in cc):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "One or more 'cc' recipients are invalid.")
        cc_list = cc

    # Ensure store structures exist
    if not isinstance(world, dict):
        world = {}
    msgs = world.get("messages")
    if not isinstance(msgs, list):
        msgs = []
        world["messages"] = msgs

    account = world.get("account")
    if not isinstance(account, str) or not account.strip():
        account = "user@gmail.com"
        world["account"] = account

    now_ms = int(time.time() * 1000)
    msg_id = f"m_{secrets.token_hex(8)}"
    ts = datetime.datetime.utcnow().isoformat() + "Z"
    msg = {
        "id": msg_id,
        "from_": account,
        "to": to,
        "cc": cc_list,
        "bcc": [],
        "subject": subject,
        "body_plain": body,
        "body_html": None,
        "label_ids": ["SENT"],
        "is_read": True,
        "is_starred": False,
        "date": now_ms,
        "internal_date": now_ms,
        "ts": ts,
        "channel_id": "C_SUPPORT",
        "user_id": "U_BOT",
        "text": body,
        "thread_ts": None,
        "reply_count": 0,
        "is_bot": True,
        "reactions": []
    }

    msgs.append(msg)
    world["messages"] = msgs
    _save("world.json", world)

    _log("ok")
    return {"message": msg}

